    {
      "xpath": null,
      "outerHTML": "<span class=\"ref\" onclick=\"location.href='https://act-rules.github.io/'\" role=\"bibliographic-reference lnik\">",
      "reason": "The span element is used as an interactive control (link) via an onclick handler, but it lacks a valid ARIA role. The role attribute value 'bibliographic-reference lnik' contains an invalid role and a misspelled role ('lnik' instead of 'link').",
      "recommendation": "Change the role attribute to 'link' and add tabindex=\"0\" along with a keyboard event handler to make it fully accessible to keyboard and screen reader users."
    }
  ],
  "summary": "A span element acting as a link control lacks a valid ARIA role due to a misspelled role value ('lnik'), violating WCAG 2.2 SC 4.1.2."
}

